sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var sysId = request.pathParams.sys_id;
    var body = request.body.data;

    if (!body) {
        response.setStatus(400);
        response.setBody({
            success: false,
            message: 'Request body is required'
        });
        return;
    }

    var gr = new GlideRecordSecure('x_2130921_caresy_0_patient');

    if (!gr.get(sysId)) {
        response.setStatus(404);
        response.setBody({
            success: false,
            message: 'Patient not found'
        });
        return;
    }

    var allowedFields = [
        'first_name',
        'last_name',
        'date_of_birth',
        'gender',
        'blood_group',
        'phone_number',
        'email',
        'address',
        'emergency_contact_name',
        'emergency_contact_phone',
        'emergency_contact_relationship',
        'patient_status',
        'active'
    ];

    var updatedFields = [];

    for (var i = 0; i < allowedFields.length; i++) {
        var field = allowedFields[i];

        if (body[field] !== undefined) {
            gr.setValue(field, body[field]);
            updatedFields.push(field);
        }
    }

    if (updatedFields.length === 0) {
        response.setStatus(400);
        response.setBody({
            success: false,
            message: 'No valid fields were provided for update'
        });
        return;
    }

    var updateResult = gr.update();

    if (!updateResult) {
        response.setStatus(500);
        response.setBody({
            success: false,
            message: 'Patient could not be updated'
        });
        return;
    }

    gr.get(sysId);

    response.setStatus(200);
    response.setBody({
        success: true,
        message: 'Patient updated successfully',
        updated_fields: updatedFields,
        patient: {
            sys_id: gr.getUniqueValue(),
            patient_number: gr.getValue('number'),
            first_name: gr.getValue('first_name'),
            last_name: gr.getValue('last_name'),
            date_of_birth: gr.getValue('date_of_birth'),
            gender: gr.getDisplayValue('gender'),
            blood_group: gr.getDisplayValue('blood_group'),
            phone_number: gr.getValue('phone_number'),
            email: gr.getValue('email'),
            address: gr.getValue('address'),
            emergency_contact_name: gr.getValue('emergency_contact_name'),
            emergency_contact_phone: gr.getValue('emergency_contact_phone'),
            emergency_contact_relationship:
                gr.getDisplayValue('emergency_contact_relationship'),
            patient_status: gr.getDisplayValue('patient_status'),
            registration_date: gr.getValue('registration_date'),
            active: gr.getValue('active') == '1'
        }
    });

})(request, response);
